/**
 * Browser Hardener Defense System
 * Integrates Thorium Shielding (Service Worker), PuppetGod (Event Interception), 
 * and Mage Hand (Command Control) into unified security layer
 */

'use strict';

const BrowserHardener = (() => {
    const config = {
        enabled: true,
        logToCloud: false,
        honeypotEndpoints: ['/api/keys', '/auth/login', '/admin/panel', '/api/v2/secrets'],
        blockedEventTypes: ['synthesized', 'beforeinput', 'pointerdown'],
        trustedOrigins: [],
        strictMode: true
    };

    const securityLog = [];
    const threatIntelligence = new Map();

    // ==================== INITIALIZATION ====================
    const init = () => {
        console.log("%c[BrowserHardener] 🛡️ Initializing Defense System", "color: #00ff00; font-weight: bold;");

        registerServiceWorker();
        initPuppetGodProtection();
        initMageHandCommander();
        initTelemetry();
        initEventMonitoring();
    };

    // ==================== SERVICE WORKER (THORIUM SHIELDING) ====================
    const registerServiceWorker = async () => {
        try {
            if ('serviceWorker' in navigator) {
                const reg = await navigator.serviceWorker.register('/hardener-sw.js', {
                    scope: '/'
                });
                console.log('[BrowserHardener] ✓ Service Worker registered');
            }
        } catch (e) {
            console.warn('[BrowserHardener] ⚠️ Service Worker registration failed:', e);
        }
    };

    // ==================== PUPPETGOD EVENT INTERCEPTION ====================
    const initPuppetGodProtection = () => {
        console.log("%c[BrowserHardener] 👁️ Activating PuppetGod Event Guardian", "color: #ff00ff;");

        const trustedEditors = [
            "[data-editor]",
            "[contenteditable]",
            "[role='textbox']",
            "textarea",
            "input[type='text']"
        ];

        const isTrustedElement = (el) => {
            if (!el) return false;
            return trustedEditors.some(sel => el.closest?.(sel));
        };

        const safeEventTypes = ['insertText', 'compositionend', 'beforeinput'];

        // Intercept synthetic events
        ['beforeinput', 'pointerdown', 'focusin', 'compositionend'].forEach(eventType => {
            document.addEventListener(eventType, (e) => {
                if (!e.isTrusted) {
                    const element = e.target;
                    const isAllowed = safeEventTypes.includes(eventType) && isTrustedElement(element);

                    logEvent({
                        type: 'synthetic_event',
                        eventType: eventType,
                        allowed: isAllowed,
                        element: element?.tagName || 'unknown',
                        timestamp: Date.now()
                    });

                    if (!isAllowed) {
                        e.preventDefault();
                        e.stopPropagation();
                        console.warn(`%c[PuppetGod] 🧨 BLOCKED: ${eventType}`, "color: orangered;");
                    }
                }
            }, true);
        });

        // Remove malicious voice/dictation UI
        setInterval(() => {
            const suspiciousElements = document.querySelectorAll(
                '[aria-label*="microphone"], [id*="speech"], [class*="voice"], [data-tracking]'
            );
            suspiciousElements.forEach(el => {
                try {
                    el.remove();
                    logEvent({ type: 'removed_element', element: el.className });
                } catch (e) {}
            });
        }, 2000);
    };

    // ==================== MAGE HAND COMMANDER ====================
    const initMageHandCommander = () => {
        console.log("%c[BrowserHardener] 🔮 Mage Hand Commander Ready", "color: #ffaa00;");

        window.HardenerCommander = {
            executeRemoteCommand: async (scriptUrl, options = {}) => {
                if (!config.strictMode && !options.confirmFirst) {
                    return executeSecureCommand(scriptUrl, options);
                }

                // Prompt user for confirmation in strict mode
                const confirmed = confirm(`Execute remote command from: ${scriptUrl}?`);
                if (confirmed) {
                    return executeSecureCommand(scriptUrl, options);
                }
                return { status: 'cancelled', reason: 'User denied' };
            },

            querySecurity: (question) => {
                return inquireSecurity(question);
            },

            updateConfig: (newConfig) => {
                Object.assign(config, newConfig);
                console.log('[BrowserHardener] ⚙️ Configuration updated');
            },

            getLogs: () => securityLog,

            getThreatIntel: () => Array.from(threatIntelligence.entries())
        };
    };

    const executeSecureCommand = async (scriptUrl, options) => {
        try {
            const response = await fetch(scriptUrl);
            if (!response.ok) throw new Error(`HTTP ${response.status}`);

            const script = await response.text();

            // Validate script before execution
            if (!validateScript(script, options)) {
                throw new Error('Script validation failed');
            }

            logEvent({
                type: 'command_execution',
                url: scriptUrl,
                status: 'approved',
                timestamp: Date.now()
            });

            // Execute in isolated context if possible
            const result = await executeIsolated(script);
            return { status: 'success', result };
        } catch (e) {
            logEvent({
                type: 'command_execution',
                url: scriptUrl,
                status: 'failed',
                error: e.message
            });
            return { status: 'error', error: e.message };
        }
    };

    const validateScript = (script, options) => {
        const blacklist = ['eval', 'innerHTML', 'document.write', 'dynamicRequire'];
        return !blacklist.some(keyword => script.includes(keyword));
    };

    const executeIsolated = (script) => {
        return new Promise((resolve) => {
            const worker = new Worker('/hardener-worker.js');
            worker.postMessage({ script });
            worker.onmessage = (e) => resolve(e.data);
            setTimeout(() => worker.terminate(), 5000);
        });
    };

    const inquireSecurity = (question) => {
        // Structured security inquiry system
        const queries = {
            'report_xss': () => logEvent({ type: 'xss_attempt', ...analyzeCurrentContext() }),
            'report_csrf': () => logEvent({ type: 'csrf_attempt', ...analyzeCurrentContext() }),
            'scan_page': () => performPageScan(),
            'status': () => ({ enabled: config.enabled, threats: threatIntelligence.size })
        };

        return queries[question]?.() || null;
    };

    // ==================== EVENT MONITORING & TELEMETRY ====================
    const initEventMonitoring = () => {
        // Monitor XSS attempts
        const originalInnerHTML = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML');
        Object.defineProperty(Element.prototype, 'innerHTML', {
            set: function(value) {
                if (detectXSSPattern(value)) {
                    logEvent({
                        type: 'xss_detected',
                        target: this.tagName,
                        content: value.slice(0, 200)
                    });
                    if (config.strictMode) return;
                }
                originalInnerHTML.set.call(this, value);
            }
        });

        // Monitor fetch requests
        const originalFetch = window.fetch;
        window.fetch = function(...args) {
            const url = args[0];
            logEvent({
                type: 'network_request',
                url: typeof url === 'string' ? url : url.url,
                timestamp: Date.now()
            });
            return originalFetch.apply(this, args);
        };

        // Monitor localStorage access
        const originalSetItem = Storage.prototype.setItem;
        Storage.prototype.setItem = function(key, value) {
            logEvent({
                type: 'storage_access',
                key,
                size: value.length
            });
            return originalSetItem.call(this, key, value);
        };
    };

    const initTelemetry = () => {
        // Periodic report of security posture
        setInterval(() => {
            const posture = {
                timestamp: Date.now(),
                threats_detected: threatIntelligence.size,
                synthetic_events_blocked: securityLog.filter(e => e.type === 'synthetic_event' && !e.allowed).length,
                xss_attempts: securityLog.filter(e => e.type === 'xss_detected').length,
                service_worker_active: navigator.serviceWorker?.controller !== undefined
            };

            console.log('[BrowserHardener] 📊 Telemetry:', posture);

            if (config.logToCloud) {
                // Send to security backend
                sendTelemetry(posture);
            }
        }, 30000);
    };

    // ==================== ANALYSIS & DETECTION ====================
    const detectXSSPattern = (content) => {
        const xssPatterns = [
            /<script[^>]*>[\s\S]*?<\/script>/gi,
            /on\w+\s*=\s*['"]/gi,
            /javascript:/gi,
            /<iframe[^>]*>/gi,
            /<object[^>]*>/gi
        ];
        return xssPatterns.some(pattern => pattern.test(content));
    };

    const analyzeCurrentContext = () => {
        return {
            url: window.location.href,
            referrer: document.referrer,
            cookies: document.cookie.length,
            localStorage: Object.keys(localStorage).length
        };
    };

    const performPageScan = () => {
        const issues = [];

        // Check for eval usage
        if (window.eval) issues.push('eval is available');

        // Check for external scripts
        document.querySelectorAll('script[src]').forEach(script => {
            const src = script.src;
            if (!config.trustedOrigins.includes(new URL(src).origin)) {
                issues.push(`Untrusted script: ${src}`);
            }
        });

        // Check for suspicious DOM attributes
        document.querySelectorAll('[onclick], [onerror], [onload]').forEach(el => {
            issues.push(`Inline handler on ${el.tagName}`);
        });

        return { issues, severity: issues.length > 0 ? 'warning' : 'safe' };
    };

    // ==================== LOGGING ====================
    const logEvent = (event) => {
        securityLog.push({
            ...event,
            timestamp: event.timestamp || Date.now()
        });

        // Track threats
        if (event.type?.includes('attack') || event.type?.includes('detected')) {
            const key = event.type;
            threatIntelligence.set(key, (threatIntelligence.get(key) || 0) + 1);
        }

        // Keep log size manageable
        if (securityLog.length > 10000) {
            securityLog.shift();
        }
    };

    const sendTelemetry = async (data) => {
        try {
            await fetch('/api/security/telemetry', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data)
            });
        } catch (e) {
            console.warn('[BrowserHardener] Telemetry send failed:', e);
        }
    };

    return {
        init,
        getConfig: () => ({ ...config }),
        getStatus: () => ({
            enabled: config.enabled,
            logsCount: securityLog.length,
            threatsDetected: threatIntelligence.size,
            serviceWorkerActive: navigator.serviceWorker?.controller !== undefined
        })
    };
})();

// Initialize on DOM ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', BrowserHardener.init);
} else {
    BrowserHardener.init();
}

