self.onmessage = function(event) {
    const { script } = event.data;

    try {
        // Validate before execution
        const validation = validateScript(script);

        if (!validation.safe) {
            self.postMessage({
                success: false,
                error: validation.errors.join('; '),
                dangerous: validation.dangerousPatterns
            });
            return;
        }

        // Execute in controlled environment
        const result = executeScript(script);
        self.postMessage({
            success: true,
            result: result
        });
    } catch (error) {
        self.postMessage({
            success: false,
            error: error.message
        });
    }
};

function validateScript(script) {
    const blacklistedKeywords = [
        'eval',
        'Function',
        'document.write',
        'innerHTML',
        'dangerouslySetInnerHTML',
        'import',
        'require',
        'fetch',
        'XMLHttpRequest',
        'WebSocket',
        'Worker',
        'SharedArrayBuffer'
    ];

    const dangerousPatterns = [
        /eval\s*\(/gi,
        /new\s+Function\s*\(/gi,
        /document\.write/gi,
        /innerHTML\s*=/gi,
        /fetch\s*\(/gi,
        /XMLHttpRequest/gi,
        /WebSocket/gi,
        /\.__proto__/gi,
        /prototype\s*\[/gi
    ];

    const errors = [];
    const found = [];

    // Check for blacklisted keywords
    blacklistedKeywords.forEach(keyword => {
        const regex = new RegExp(`\\b${keyword}\\b`, 'gi');
        if (regex.test(script)) {
            errors.push(`Blacklisted keyword: ${keyword}`);
            found.push(keyword);
        }
    });

    // Check for dangerous patterns
    dangerousPatterns.forEach(pattern => {
        if (pattern.test(script)) {
            const match = script.match(pattern);
            errors.push(`Dangerous pattern detected: ${match[0]}`);
            found.push(match[0]);
        }
    });

    return {
        safe: errors.length === 0,
        errors,
        dangerousPatterns: found
    };
}

function executeScript(script) {
    // Create isolated function scope
    const sandbox = {
        console,
        Math,
        JSON,
        Date,
        Array,
        Object,
        String,
        Number,
        Boolean,
        RegExp,
        Promise,
        // Explicitly denied
        fetch: undefined,
        XMLHttpRequest: undefined,
        eval: undefined,
        Function: undefined
    };

    // Create scoped execution
    const fn = new Function(...Object.keys(sandbox), script);
    const result = fn(...Object.values(sandbox));

    return result;
}

